def versioned_urls(markup):
    def replace(match):
        value = html.unescape(match.group(2))
        parts = urlsplit(value)
        if parts.scheme or parts.netloc or not parts.path or Path(parts.path).suffix not in ('.html','.css','.js','.svg'):
            return match.group(0)
        query = dict(parse_qsl(parts.query))
        query['v'] = BUILD
        return f'{match.group(1)}="{esc(urlunsplit((parts.scheme,parts.netloc,parts.path,urlencode(query),parts.fragment)))}"'
    return re.sub(r'(href|src)="([^"]*)"',replace,markup)

