def archive():
    items=[]
    for p in DATA['projects']:
        if p.get('featured') or p.get('placement')=='research': continue
        title=esc(p['title'])
        if p.get('url'): title=f'<a href="{esc(p["url"])}" target="_blank" rel="noopener noreferrer">{title} ↗</a>'
        description=esc(p['description'])
        if p.get('course_name') and p.get('url'):
            course=esc(p['course_name'])
            description=description.replace(course,f'<a href="{esc(p["url"])}" target="_blank" rel="noopener noreferrer">{course}</a>',1)
        for label,url in p.get('description_links',{}).items():
            description=description.replace(esc(label),f'<a href="{esc(url)}" target="_blank" rel="noopener noreferrer">{esc(label)}</a>',1)
        items.append(f'<article class="archive-item"><h3>{title}</h3><p>{description}</p></article>')
    return '<details class="archive"><summary><span>More projects</span><span aria-hidden="true">+</span></summary><div class="archive-list">'+''.join(items)+'</div></details>'

